// 오디세이(2026, 크리스토퍼 놀란) 장소 데이터
const ODYSSEY_LOCATIONS = [
  { id: 'favignana_castle', order: 1, modernName: '카스텔로 디 산타 카테리나 (파비냐나 섬, 이탈리아 시칠리아)', lat: 37.9336, lng: 12.3251, description: '영화 《오디세이》에서 이타카 왕궁의 외경으로 쓰인 실제 장소. 시칠리아 서쪽 에가디 제도의 최대 섬 파비냐나의 산타 카테리나 산 정상에 서 있는 15세기 성채로, 접근로가 없어 촬영 장비는 삭도(funicular)로, 배우와 스태프는 매일 도보로 산을 올라야 했다. 성 옆에는 에우마이오스가 유배되는 돼지우리 세트도 함께 지어졌다.', description_en: 'The real fortress used for the exterior of Odysseus and Penelope\'s palace at \'Ithaca\'. A 15th-century castle crowning Monte Santa Caterina on Favignana, the largest of Sicily\'s Egadi Islands — so remote that equipment needed a funicular lift while cast and crew hiked up daily.', tag: '실제 촬영지 — 이타카 왕궁 외경 (놀란 감독 오디세이)', tag_en: 'REAL SETTING — Ithaca palace exterior, filmed here', travelTip: '폐성이라 도보로만 접근 가능(약 30~45분 가파른 등반). 파비냐나 항에서 페리로 진입.', travelTip_en: 'Abandoned castle, reachable only on foot (30–45 min steep climb). Ferry in via Favignana harbour.' },
  { id: 'universal_studios_la', order: 2, modernName: '유니버설 스튜디오 할리우드 스테이지12 (미국 로스앤젤레스)', lat: 34.1381, lng: -118.3534, description: '이타카 왕궁의 실내 — 페넬로페가 밤마다 수의를 짜는 방과 결말부 알현실 대결 장면 — 이 실제로 세워진 스튜디오. 파비냐나에서 찍은 외경과 이어붙여 하나의 궁전처럼 완성됐다.', description_en: 'The interior of Ithaca\'s palace — where Penelope weaves her endless shroud, and where the film\'s climactic confrontation unfolds — was built on Stage 12 here, digitally stitched to the Favignana exterior.', tag: '실제 촬영지 — 이타카 왕궁 실내 세트', tag_en: 'REAL SETTING — Ithaca palace interior, built on this soundstage', travelTip: '스튜디오 투어(관광용)로 일부 구역 견학 가능.', travelTip_en: 'Some areas viewable via the public studio tour.' },
  { id: 'aeolian_vulcano', order: 3, modernName: '불카노 섬 (이탈리아 에올리에 제도)', lat: 38.4041, lng: 14.9619, description: '오디세우스 일행이 포세이돈의 시험을 겪는 \'아이올리아\' 섬 촬영지 중 하나. 시칠리아 북쪽 활화산 군도인 에올리에 제도에 속한다.', description_en: 'One of the volcanic Aeolian Islands used to stand in for the mythological island of \'Aeolia\', where Odysseus and his crew are subjected to trials by Poseidon.', tag: '실제 촬영지 — 아이올리아 촬영지 (에올리에 제도)', tag_en: 'REAL SETTING — \'Aeolia\' filmed on this Aeolian island', travelTip: '리파리에서 페리로 연결. 활화산 지형이라 등반 시 화산 가스 주의.', travelTip_en: 'Reached by ferry from Lipari; take care of volcanic gas near the crater.' },
  { id: 'aeolian_lipari', order: 4, modernName: '리파리 섬 (이탈리아 에올리에 제도)', lat: 38.4692, lng: 14.9506, description: '에올리에 제도에서 가장 큰 섬으로, \'아이올리아\' 시퀀스의 주 촬영 거점. 섬 남서쪽 끝에는 세이렌의 노래가 울려 퍼지는 \'피에트라 델 바뇨\' 암초 해역이 있다.', description_en: 'The largest of the Aeolian Islands and the main base for the \'Aeolia\' sequence. Off its southwestern tip lie the waters of the Pietra del Bagno shoal, used for the Sirens\' song scene.', tag: '실제 촬영지 — 아이올리아·세이렌 해역 촬영 거점', tag_en: 'REAL SETTING — Base for \'Aeolia\' and Sirens sequences', travelTip: '카타니아 공항→밀라초 기차/버스→리파리행 페리로 이동.', travelTip_en: 'Fly to Catania, train/bus to Milazzo, then ferry to Lipari.' },
  { id: 'faraglioni_lipari', order: 5, modernName: '리파리의 파랄리오니(피에트라 룽가·피에트라 메날다)', lat: 38.454, lng: 14.93, description: '호메로스가 \'방황하는 바위\'의 영감을 얻었다고 여겨지는 리파리 남서쪽의 기괴한 수직 암석 첨탑. 옛 화산의 \'목\' 부분만 침식으로 남은 것으로, 영화에서 그대로 \'방황하는 바위\' 장면에 쓰였다.', description_en: 'The bizarre vertical sea-stacks off southwestern Lipari believed to have inspired Homer\'s \'Wandering Rocks\' — the eroded volcanic \'necks\' of an extinct volcano, used unaltered as the film\'s Wandering Rocks.', tag: '실제 촬영지 — 방황하는 바위 (호메로스의 영감으로 추정되는 실제 지형)', tag_en: 'REAL SETTING — \'Wandering Rocks\' filmed here; believed to be Homer\'s inspiration', travelTip: '보트 투어로만 접근 가능한 해상 지형.', travelTip_en: 'Only accessible by boat tour.' },
  { id: 'pietra_del_bagno', order: 6, modernName: '피에트라 델 바뇨 암초 해역 (리파리 서쪽)', lat: 38.475, lng: 14.915, description: '선원들이 밀랍으로 귀를 막고 오디세우스가 돛대에 몸을 묶인 채 지나간 \'세이렌\' 시퀀스의 실제 촬영 해역.', description_en: 'The real waters where the crew, ears sealed with wax, and Odysseus, bound to the mast, sail past the Sirens.', tag: '실제 촬영지 — 세이렌의 노래 장면', tag_en: 'REAL SETTING — Sirens\' song scene filmed in these waters', travelTip: '리파리에서 보트로 접근.', travelTip_en: 'Accessible by boat from Lipari.' },
  { id: 'basiluzzo_scylla', order: 7, modernName: '바실루초 섬·스코글리오 스피나촐라 (에올리에 제도)', lat: 38.5622, lng: 15.1719, description: '카리브디스의 소용돌이를 피해 스킬라의 협곡으로 들어선 오디세우스의 배가 6명의 병사를 잃는 장면의 촬영지. 리파리와 스트롬볼리 사이의 무인도 바실루초와 그 앞의 뾰족한 암초 스코글리오 스피나촐라가 협곡 역할을 했다.', description_en: 'Where Odysseus\'s ship loses six men to six-headed Scylla while avoiding Charybdis\'s whirlpool. The uninhabited island of Basiluzzo and the jagged sea-stack Scoglio Spinazzola in front of it play the deadly channel.', tag: '실제 촬영지 — 스킬라 협곡 장면', tag_en: 'REAL SETTING — Scylla\'s channel filmed here', travelTip: '정기 여객선이 없는 무인도. 리파리·파나레아에서 보트 투어 예약 필요.', travelTip_en: 'Uninhabited, no regular ferries — book a boat tour from Lipari or Panarea.' },
  { id: 'essaouira_morocco', order: 8, modernName: '에사우이라 (모로코 대서양 연안)', lat: 31.5085, lng: -9.7595, description: '트로이 병사들이 \'아테나에게 바치는 제물\'이라 믿고 목마를 성으로 끌고 가는 해변 장면이 촬영된 모로코의 대서양 항구 도시. 영화에서는 목마가 포세이돈에게 바치는 제물로 재해석되어 모래에 반쯤 잠긴 모습으로 등장한다.', description_en: 'The Moroccan Atlantic port where the beach scene of the Trojans hauling away the \'gift to Athena\' — reimagined here as an offering to Poseidon, half-buried in sand — was filmed.', tag: '실제 촬영지 — 트로이 목마 발견 해변', tag_en: 'REAL SETTING — Trojan Horse discovery beach, filmed here', travelTip: '마라케시에서 버스로 약 3시간.', travelTip_en: 'About a 3-hour bus ride from Marrakech.' },
  { id: 'ait_ben_haddou', order: 9, modernName: '아이트 벤하두 (모로코 와르자자트 인근)', lat: 31.0472, lng: -7.1319, description: '영화 속 \'트로이\' 성벽 도시로 등장한 유네스코 세계유산 카스바 마을. 아테나 신전을 포함해 60여 개의 임시 구조물이 추가로 지어졌고, 2.5에이커(약 1만㎡) 규모로 목마 작전 이후 도시가 불타는 장면이 촬영됐다.', description_en: 'The UNESCO World Heritage ksar that became the walled city of \'Troy\' — 60 extra structures including a \'Temple of Athena\' were built across 2.5 acres for the city\'s spectacular destruction sequence.', tag: '실제 촬영지 — 트로이 성', tag_en: 'REAL SETTING — the city of Troy, filmed here', travelTip: '마라케시에서 약 185km. 버스로 접근 가능, 인근 와르자자트 스튜디오도 연계 방문 가능.', travelTip_en: 'About 115 miles from Marrakech; accessible by bus, combine with Ouarzazate\'s Atlas Studios.' },
  { id: 'tahanaout_morocco', order: 10, modernName: '타하나우트 (모로코 엘하우즈)', lat: 31.35, lng: -7.95, description: '아이트 벤하두와 함께 트로이 성의 일부 장면이 추가로 촬영된 마라케시 인근 시장 마을.', description_en: 'A market town near Marrakech where additional parts of the \'Troy\' city scenes were filmed, alongside Aït Ben Haddou.', tag: '실제 촬영지 — 트로이 시가지 보조 촬영지', tag_en: 'REAL SETTING — additional \'Troy\' street scenes filmed here', travelTip: '마라케시에서 남쪽으로 약 30km.', travelTip_en: 'About 20 miles south of Marrakech.' },
  { id: 'dune_blanche', order: 11, modernName: '화이트 듄(다클라 인근, 서사하라)', lat: 23.8, lng: -15.95, description: '칼립소의 섬 \'오기기아\'의 해변으로 쓰인, 다클라에서 약 30km 떨어진 새하얀 초승달 모양의 사구. 로터스 나무의 꽃을 먹고 7년간 기억을 잃은 오디세우스가 칼립소와 지내는 장면의 배경이다. 서사하라는 유엔이 비자치지역으로 분류하고 모로코가 실효 지배 중인 분쟁 지역으로, 이 장소 사용을 두고 촬영 전 국제적 논란이 있었다.', description_en: 'The pristine crescent-shaped White Dune near Dakhla used as the beach of Calypso\'s isle \'Ogygia\', where Odysseus loses seven years of memory to the lotus flower. Filming here drew international controversy, as Western Sahara is a UN-listed non-self-governing territory administered by Morocco.', tag: '실제 촬영지 — 칼립소의 섬 \'오기기아\' 해변', tag_en: 'REAL SETTING — Calypso\'s \'Ogygia\' beach, filmed here', travelTip: '다클라에서 약 20마일. 카이트서핑 명소이나 분쟁지역 특성상 검문소 등 유의사항 확인 필요.', travelTip_en: 'About 20 miles from Dakhla, popular with kite surfers; check regional sensitivities and checkpoints before visiting.' },
  { id: 'voidokilia_beach', order: 12, modernName: '보이도킬리아 해변 (그리스 펠로폰네소스 메세니아)', lat: 36.9575, lng: 21.6669, description: '말굽 모양의 아름다운 만으로, 영화 속 \'키클롭스의 섬\'—오디세우스 일행이 마을을 불태우고 폴리페무스의 동굴과 마주치는 곳—으로 쓰였다.', description_en: 'The gorgeous horseshoe-shaped cove used as the \'Island of the Cyclopes\', where the crew recklessly burns a village before stumbling on Polyphemus\'s cave.', tag: '실제 촬영지 — 키클롭스의 섬', tag_en: 'REAL SETTING — \'Island of the Cyclopes\', filmed here', travelTip: '칼라마타 국제공항에서 펠로폰네소스 진입.', travelTip_en: 'Reach the Peloponnese via Kalamata International Airport.' },
  { id: 'nestors_cave', order: 13, modernName: '네스토르의 동굴 (보이도킬리아 해변 위, 그리스)', lat: 36.959, lng: 21.666, description: '기원전 6000년부터 사람이 살았다는 실제 동굴로, 전설에 따르면 필로스의 왕 네스토르가 소 떼를 기르던 곳이다. 영화에서는 폴리페무스의 동굴 내부로 그대로 사용되어, CG 없이 차갑고 울리는 진짜 동굴 안에서 촬영됐다.', description_en: 'A real cave inhabited since 6000 BC, legendarily where Nestor, King of Pylos, kept his cattle. The film used it, unaltered, as the interior of Polyphemus\'s cave — shot for real in its cold, echoing chamber rather than on a soundstage.', tag: '실제 촬영지 — 폴리페무스의 동굴 내부', tag_en: 'REAL SETTING — interior of Polyphemus\'s cave, filmed here', travelTip: '동굴 내부는 비공개. 입구만 먼발치에서 조망 가능.', travelTip_en: 'Not open to visitors; the entrance can only be viewed from a distance.' },
  { id: 'methoni_castle', order: 14, modernName: '메토니 성·부르치 (그리스 펠로폰네소스)', lat: 36.8236, lng: 21.7048, description: '16세기에 축조되고 이후 베네치아인들이 증축한 요새. 육지와 돌길로 이어진 8각 탑 \'부르치\'가 스파르타 왕 메넬라오스와 왕비 헬레네의 궁전으로 등장해, 텔레마코스가 아버지의 소식을 구하러 찾아가는 곳으로 쓰였다.', description_en: 'A 16th-century fortress later enhanced by the Venetians; its octagonal tower \'the Bourtzi\', linked to land by a stone walkway, became the palace of Menelaus and Helen of Sparta, where Telemachus seeks news of his father.', tag: '실제 촬영지 — 스파르타 궁전 (메넬라오스·헬레네)', tag_en: 'REAL SETTING — palace of Menelaus and Helen, filmed here', travelTip: '화요일 휴무, 입장료 있음.', travelTip_en: 'Closed Tuesdays; admission fee applies.' },
  { id: 'acrocorinth', order: 15, modernName: '아크로코린토스 (그리스 펠로폰네소스)', lat: 37.9033, lng: 22.8783, description: '코린토스 시가지를 내려다보는 산상 요새로, 실제 미케네에서 북동쪽으로 약 190km 떨어져 있음에도 아가멤논이 귀향해 클리타임네스트라의 냉대를 받는 \'미케네\' 회상 장면 촬영지로 쓰였다.', description_en: 'A hilltop fortress overlooking Corinth — though nearly 120 miles from the real Mycenae — used for flashbacks of Agamemnon\'s homecoming to a hostile welcome from Clytemnestra in \'Mycenae\'.', tag: '실제 촬영지 — 미케네 회상 장면 (아가멤논·클리타임네스트라)', tag_en: 'REAL SETTING — \'Mycenae\' flashback, filmed here', travelTip: '입장 무료이나 경사가 가파르고 노면이 고르지 않음.', travelTip_en: 'Free entry, but paths are steep and uneven.' },
  { id: 'culbin_forest', order: 16, modernName: '컬빈 숲 (스코틀랜드 애버딘셔·모레이 해안)', lat: 57.627, lng: -3.648, description: '이너네스 북동쪽 약 40km, 모레이만 해안의 광활한 소나무 숲. 오디세우스 일행이 \'아이아이아\'의 해변으로 착각하고 상륙했다가 갑옷을 두른 거인족 라이스트뤼고네스에게 습격당하는 장면이 촬영됐다.', description_en: 'A vast pine forest on the Moray Firth coast, about 25 miles northeast of Inverness. Here Odysseus\'s men mistake the shore for the coast of \'Aeaea\' and are attacked by the armoured giant Laestrygonians.', tag: '실제 촬영지 — 라이스트뤼고네스 습격 장면', tag_en: 'REAL SETTING — Laestrygonian attack, filmed here', travelTip: '포레스 인근 A96 도로변 주차장에서 진입.', travelTip_en: 'Enter via the car park off the A96 near Forres.' },
  { id: 'findlater_castle', order: 17, modernName: '핀들레이터 성 (스코틀랜드 애버딘셔)', lat: 57.6706, lng: -2.8319, description: '컬빈 숲에서 동쪽으로 약 65km 떨어진 해안 절벽 위 폐성 유적. 이곳 인근에 키르케의 소박한 거처 세트가 지어져, 병사들을 돼지로 만드는 장면이 촬영됐다. 성벽의 고고학적 흔적을 보존하기 위해 세트는 성의 부속 구역 쪽에 조심스레 세워졌다.', description_en: 'A ruined clifftop castle about 40 miles east of Culbin Forest. Circe\'s modest home was built nearby, near the castle\'s surviving bailey, taking care to preserve the site\'s archaeology, for the scene where the crew are turned into pigs.', tag: '실제 촬영지 — 키르케의 거처', tag_en: 'REAL SETTING — Circe\'s home, filmed here', travelTip: '컬렌 인근 A98 도로. 좁은 길과 절벽 낙차에 유의.', travelTip_en: 'Off the A98 near Cullen; take care on narrow paths with steep drops.' },
  { id: 'hjorleifshofdi', order: 18, modernName: '이외를레이프스회이디 (아이슬란드 남부)', lat: 63.427, lng: -18.757, description: '비크 동쪽, 화산 평원에 둘러싸인 검은 모래 해변의 외딴 곶. \'얼음의 강과 불의 강이 만나는 곳\'이라는 키르케의 묘사대로 저승 \'하데스\'의 배경으로 촬영되어, 오디세우스가 망자들을 소환해 테이레시아스의 예언을 듣는 장면이 펼쳐진다.', description_en: 'A steep, isolated black-sand headland east of Vík, surrounded by volcanic flats. Matching Circe\'s description of a place \'where the river of fire meets the river of ice\', it served as the underworld realm of \'Hades\' where Odysseus summons the dead to hear Tiresias\'s prophecy.', tag: '실제 촬영지 — 저승 \'하데스\' 소환 장면', tag_en: 'REAL SETTING — the underworld \'Hades\', filmed here', travelTip: '비크에서 동쪽으로 약 185km, 1번 국도.', travelTip_en: 'About 115 miles east of Vík via Route 1.' },
  { id: 'landeyjahofn', order: 19, modernName: '란데이야회픈 항구 (아이슬란드)', lat: 63.4472, lng: -20.115, description: '오디세우스의 배로 쓰인 바이킹 복원선 \'드라켄 하랄 호르파그레\'가 정박했던 아이슬란드 남부의 작은 항구.', description_en: 'The small southern Icelandic port where the Viking replica ship Draken Harald Hårfagre, used as Odysseus\'s vessel, was moored between filming locations.', tag: '실제 촬영지 — 오디세우스의 배 정박지', tag_en: 'REAL SETTING — mooring port for Odysseus\'s ship', travelTip: '레이캬비크에서 남쪽 해안도로로 접근.', travelTip_en: 'Accessible via the south coast road from Reykjavík.' },
  { id: 'kalkara_malta', order: 20, modernName: '칼카라 지중해 필름 스튜디오 (몰타)', lat: 35.8925, lng: 14.525, description: '세계 최대급 수조 시설을 갖춘 몰타의 촬영 스튜디오. 난파선 장면과 근거리 해상 전투 등 수중 촬영 전체가 이곳에서 실사 특수효과와 새로 개발된 IMAX 카메라로 촬영됐다.', description_en: 'A Maltese studio with some of the world\'s largest water tanks. All underwater photography — shipwrecks, close-range sea battles — was shot here using practical effects and newly adapted IMAX cameras.', tag: '실제 촬영지 — 수중 촬영 스튜디오', tag_en: 'REAL SETTING — underwater filming studio', travelTip: '발레타에서 버스로 접근 가능한 칼카라 지역.', travelTip_en: 'Kalkara is reachable by bus from Valletta.' },
  { id: 'real_ithaca', order: 21, modernName: '이타키 섬 (그리스 이오니아 해)', lat: 38.4529, lng: 20.6532, description: '고대부터 현재까지 \'오디세우스의 고향 이타카\'로 지목되어 온 실제 그리스 이오니아해의 섬. 영화의 이타카 궁전은 시칠리아 파비냐나에서 촬영됐지만, 신화 속 이타카는 바로 이 섬으로 전통적으로 비정된다.', description_en: 'The real Ionian island traditionally identified, since antiquity, as Odysseus\'s homeland of Ithaca. While the film\'s palace was shot on Sicily\'s Favignana, the mythological Ithaca has long been placed here.', tag: '실제 신화 속 지명 — 오디세우스의 실제 고향으로 비정되는 섬', tag_en: 'REAL SETTING — traditionally identified as Odysseus\'s real Ithaca', travelTip: '패트라·이구메니차 등에서 페리로 접근.', travelTip_en: 'Reachable by ferry from Patras or Igoumenitsa.' },
  { id: 'real_troy_hisarlik', order: 22, modernName: '트로이 유적 히사를리크 (튀르키예 차낙칼레)', lat: 39.9576, lng: 26.2386, description: '하인리히 슐리만이 1870년대에 발굴해 실제 트로이 전쟁의 무대로 널리 인정받는 고고학 유적. 영화의 \'트로이\'는 모로코 아이트 벤하두에서 촬영됐지만, 실제 트로이는 튀르키예 다르다넬스 해협 인근의 이 언덕이다.', description_en: 'The archaeological site excavated by Heinrich Schliemann in the 1870s, widely accepted as the real setting of the Trojan War. The film\'s \'Troy\' was shot in Morocco\'s Aït Ben Haddou, but the actual Troy is this mound near the Dardanelles in Turkey.', tag: '실제 신화 속 지명 — 실제 트로이 전쟁 유적지', tag_en: 'REAL SETTING — the real archaeological site of Troy', travelTip: '차낙칼레에서 차량으로 약 30분.', travelTip_en: 'About a 30-minute drive from Çanakkale.' },
  { id: 'real_pylos_nestor', order: 23, modernName: '필로스 네스토르 궁전 유적 (그리스 펠로폰네소스)', lat: 37.0186, lng: 21.6942, description: '\'모래의 필로스\'로 불리며 지혜로운 노장 네스토르가 다스렸다는 실제 미케네 문명 궁전 유적. 영화 촬영지인 \'네스토르의 동굴\'과 도보로 멀지 않은 거리에 있어, 신화와 촬영지가 실제로 가까이 겹치는 드문 사례다.', description_en: 'The real Mycenaean-era palace ruin of \'sandy Pylos\', ruled in myth by wise old Nestor. It sits an easy distance from the film\'s \'Nestor\'s Cave\' location — a rare case where myth and shooting location genuinely overlap.', tag: '실제 신화 속 지명 — 네스토르 왕의 실제 궁전 유적', tag_en: 'REAL SETTING — real palace ruins of King Nestor', travelTip: '칼라마타에서 차량으로 약 1시간.', travelTip_en: 'About a 1-hour drive from Kalamata.' },
  { id: 'real_sparta', order: 24, modernName: '고대 스파르타 유적 (그리스 라코니아)', lat: 37.0798, lng: 22.4234, description: '메넬라오스와 헬레네가 다스렸다는 신화 속 스파르타의 실제 위치. 영화에서는 메토니 성이 이를 대신했지만, 실제 고대 스파르타 유적은 펠로폰네소스 남부 라코니아 평원에 있다.', description_en: 'The real location of the mythological Sparta ruled by Menelaus and Helen. The film substituted Methoni Castle, but the actual ancient Spartan ruins lie in the Laconian plain of the southern Peloponnese.', tag: '실제 신화 속 지명 — 실제 스파르타 유적', tag_en: 'REAL SETTING — real ruins of ancient Sparta', travelTip: '스파르티(현대 도시) 인근에 위치.', travelTip_en: 'Located near the modern town of Sparti.' },
  { id: 'real_mycenae', order: 25, modernName: '미케네 유적 (그리스 아르골리스)', lat: 37.7307, lng: 22.7565, description: '아가멤논이 실제로 다스렸다고 여겨지는 미케네 문명의 심장부이자 유네스코 세계유산. 영화는 이곳에서 북동쪽으로 약 24마일 떨어진 아크로코린토스에서 미케네 회상 장면을 촬영했다.', description_en: 'The UNESCO-listed heart of Mycenaean civilization, believed to be Agamemnon\'s real seat of power. The film shot its Mycenae flashbacks 24 miles northeast of here, at Acrocorinth.', tag: '실제 신화 속 지명 — 아가멤논의 실제 왕도', tag_en: 'REAL SETTING — Agamemnon\'s real royal seat', travelTip: '미케네 마을 인근, \'사자의 문\' 등 유적 관람 가능.', travelTip_en: 'Near Mykines village; visit the Lion Gate and other ruins.' },
  { id: 'real_cape_malea', order: 26, modernName: '말레아곶 (그리스 펠로폰네소스 남단)', lat: 36.431, lng: 23.191, description: '호메로스 원전에서 트로이를 떠난 오디세우스의 함대가 폭풍에 휘말려 항로를 완전히 벗어나기 시작한 실제 지점으로 지목되는 곶. 고대부터 뱃사람들에게 악명 높은 험로였다.', description_en: 'The real cape traditionally identified in Homer\'s text as where Odysseus\'s fleet, blown by storms, was first driven wildly off course on the way home from Troy — notoriously treacherous for sailors since antiquity.', tag: '실제 신화 속 지명 — 오디세우스가 항로를 이탈한 지점(원작)', tag_en: 'REAL SETTING — where Odysseus was blown off course, per Homer', travelTip: '펠로폰네소스 최남단, 접근이 어려운 험한 해안.', travelTip_en: 'The southernmost tip of the Peloponnese; a rugged, hard-to-reach coastline.' },
  { id: 'real_djerba', order: 27, modernName: '제르바 섬 (튀니지)', lat: 33.8076, lng: 10.8451, description: '고대부터 \'로토파고이(연꽃 먹는 자들의 나라)\'로 전통적으로 비정되어 온 튀니지의 섬. 이 영화 각색에서는 로터스 나무의 꽃이 칼립소의 섬 오기기아 에피소드로 자리를 옮겨 재구성됐다.', description_en: 'The Tunisian island traditionally identified since antiquity as the land of the Lotus-eaters. This adaptation relocates the lotus-flower motif to the Ogygia/Calypso episode instead.', tag: '실제 신화 속 지명 — 로토파고이족의 땅으로 비정되는 섬', tag_en: 'REAL SETTING — traditionally identified as the Lotus-eaters\' island', travelTip: '튀니지 본토에서 다리로 연결.', travelTip_en: 'Connected to the Tunisian mainland by a causeway bridge.' },
  { id: 'real_strait_messina', order: 28, modernName: '메시나 해협 (이탈리아 시칠리아·칼라브리아 사이)', lat: 38.2333, lng: 15.6167, description: '스킬라와 카리브디스가 마주 보고 있었다는 전통적 비정지. 시칠리아와 이탈리아 본토 사이의 좁은 해협으로, 실제로 조류가 거세 고대 뱃사람들에게 공포의 대상이었다.', description_en: 'The strait traditionally identified as where Scylla and Charybdis faced each other — the narrow channel between Sicily and mainland Italy, genuinely known for treacherous currents that terrified ancient sailors.', tag: '실제 신화 속 지명 — 스킬라·카리브디스의 실제 비정지', tag_en: 'REAL SETTING — traditional real-world site of Scylla and Charybdis', travelTip: '메시나(시칠리아)~레조 칼라브리아(본토) 페리로 횡단 가능.', travelTip_en: 'Crossable by ferry between Messina (Sicily) and Reggio Calabria (mainland).' },
  { id: 'real_mount_etna', order: 29, modernName: '에트나 화산 (이탈리아 시칠리아)', lat: 37.751, lng: 14.9934, description: '유럽 최대의 활화산으로, 전통적으로 폴리페무스를 비롯한 키클롭스 형제들의 고향으로 여겨져 왔다. 화산 폭발음이 \'눈먼 거인의 울부짖음\'으로 신화화되었다는 설도 있다.', description_en: 'Europe\'s largest active volcano, traditionally regarded as the homeland of Polyphemus and his fellow Cyclopes — some traditions hold that its eruptions were mythologized as the blinded giant\'s roars.', tag: '실제 신화 속 지명 — 키클롭스족의 전통적 고향', tag_en: 'REAL SETTING — traditional homeland of the Cyclopes', travelTip: '카타니아에서 등반 투어 이용 가능.', travelTip_en: 'Guided ascents available from Catania.' },
  { id: 'real_monte_circeo', order: 30, modernName: '몬테 치르체오 (이탈리아 라치오)', lat: 41.2333, lng: 13.0667, description: '고대 로마 시대부터 마녀 키르케의 섬 \'아이아이아\'로 비정되어 온 이탈리아 서해안의 곶. 영화는 이 에피소드를 스코틀랜드 애버딘셔에서 촬영했지만, 전통적인 신화 지리는 이곳을 가리킨다.', description_en: 'A promontory on Italy\'s west coast identified since Roman antiquity as Circe\'s island \'Aeaea\'. The film shot this episode in Aberdeenshire, Scotland, but traditional mythological geography points here.', tag: '실제 신화 속 지명 — 키르케의 섬 \'아이아이아\'의 실제 비정지', tag_en: 'REAL SETTING — traditional real-world site of Circe\'s Aeaea', travelTip: '로마에서 남쪽으로 약 100km, 국립공원으로 지정.', travelTip_en: 'About 60 miles south of Rome; designated a national park.' },
  { id: 'real_gozo_calypso', order: 31, modernName: '고초 섬 칼립소의 동굴 (몰타)', lat: 36.0443, lng: 14.2686, description: '고대부터 칼립소의 섬 \'오기기아\'로 전해 내려오는 몰타 제도의 고초 섬. 실제로 \'칼립소의 동굴\'이라는 이름의 명소가 있다. 영화는 이 에피소드를 서사하라의 화이트 듄에서 촬영했지만, 지중해 신화 전통은 이곳을 오기기아로 지목해왔다.', description_en: 'The island of Gozo in the Maltese archipelago, traditionally identified since antiquity as Calypso\'s isle \'Ogygia\' — it even has a landmark literally called \'Calypso\'s Cave\'. The film shot this episode at Western Sahara\'s White Dune, but Mediterranean tradition points here.', tag: '실제 신화 속 지명 — 오기기아의 전통적 비정지 (\'칼립소의 동굴\')', tag_en: 'REAL SETTING — traditional site of Ogygia, home to \'Calypso\'s Cave\'', travelTip: '몰타 본섬에서 페리로 고초 섬 진입.', travelTip_en: 'Reach Gozo by ferry from mainland Malta.' },
  { id: 'real_li_galli', order: 32, modernName: '리 갈리 제도 (이탈리아 포지타노 인근)', lat: 40.5833, lng: 14.4667, description: '나폴리만 소렌토 반도 앞바다의 작은 군도로, 고대부터 세이렌들이 살던 바위섬으로 전해진다. 영화의 세이렌 시퀀스는 시칠리아 리파리 해역에서 촬영됐다.', description_en: 'A small archipelago off the Sorrentine Peninsula near Positano, traditionally said since antiquity to be home to the Sirens. The film\'s Sirens sequence was shot in the waters off Lipari, Sicily.', tag: '실제 신화 속 지명 — 세이렌 바위의 전통적 비정지', tag_en: 'REAL SETTING — traditional site of the Sirens\' rocks', travelTip: '포지타노·아말피에서 보트 투어로 접근.', travelTip_en: 'Accessible by boat tour from Positano or Amalfi.' },
  { id: 'real_cape_tainaron', order: 33, modernName: '타이나론곶(마타판곶) (그리스 마니 반도)', lat: 36.3833, lng: 22.4833, description: '고대 그리스인들이 저승 하데스로 통하는 실제 입구 중 하나로 믿었던 곶. 영화의 저승 시퀀스는 아이슬란드에서 촬영됐지만, 신화 지리학은 이곳을 \'망자들의 문턱\'으로 여겼다.', description_en: 'A cape ancient Greeks believed to be a real entrance to the underworld of Hades. The film\'s underworld sequence was shot in Iceland, but mythological geography placed \'the threshold of the dead\' here.', tag: '실제 신화 속 지명 — 저승 입구로 여겨진 실제 곶', tag_en: 'REAL SETTING — traditionally believed entrance to the underworld', travelTip: '마니 반도 최남단, 험준한 산길로 접근.', travelTip_en: 'The southern tip of the Mani Peninsula; reached via rugged mountain roads.' },
  { id: 'real_corfu', order: 34, modernName: '코르푸(케르키라) 섬 (그리스)', lat: 39.6243, lng: 19.9217, description: '오디세우스를 마지막으로 돌봐 이타카까지 데려다준 파이아케스인들의 나라 \'스케리아\'로 전통적으로 비정되는 섬. 이 영화 각색에서는 오디세우스가 뗏목으로 표류하다 이타카에 곧장 닿는 것으로 각색되어, 파이아케스 에피소드 자체가 생략됐다.', description_en: 'The island traditionally identified as \'Scheria\', land of the Phaeacians who gave Odysseus his final ride home. This adaptation cuts the Phaeacian episode entirely — Odysseus drifts by raft straight to Ithaca instead.', tag: '실제 신화 속 지명 — 원작 속 파이아케스인의 나라 (영화에서는 생략된 에피소드)', tag_en: 'REAL SETTING — Homer\'s land of the Phaeacians (episode cut from the film)', travelTip: '그리스 본토·이탈리아에서 페리로 연결.', travelTip_en: 'Connected by ferry to mainland Greece and Italy.' },
  { id: 'real_maroneia', order: 35, modernName: '마로네이아(고대 이스마로스) (그리스 트라키아)', lat: 40.8894, lng: 25.5389, description: '트로이를 떠난 오디세우스 일행이 처음으로 약탈한 키코네스족의 도시 \'이스마로스\'로 전통적으로 비정되는 그리스 북동부 트라키아의 해안 마을.', description_en: 'A coastal town in northeastern Greek Thrace traditionally identified as \'Ismarus\', the city of the Cicones — the first place Odysseus\'s men raid after leaving Troy.', tag: '실제 신화 속 지명 — 키코네스족 이스마로스의 비정지', tag_en: 'REAL SETTING — traditional site of Ismarus, city of the Cicones', travelTip: '코모티니 인근, 고대 극장 등 유적 존재.', travelTip_en: 'Near Komotini; ruins including an ancient theatre survive.' },
  { id: 'real_isthmus_corinth', order: 36, modernName: '코린토스 지협 (그리스)', lat: 37.935, lng: 22.935, description: '펠로폰네소스 반도와 그리스 본토를 잇는 좁은 지협으로, 아크로코린토스(영화의 미케네 대역 촬영지)로 이어지는 관문이자 고대 그리스 육상·해상 교통의 요충지였다.', description_en: 'The narrow isthmus linking the Peloponnese to mainland Greece — the gateway to Acrocorinth (the film\'s Mycenae stand-in) and a crucial ancient crossroads of land and sea routes.', tag: '실제 신화 속 지명 — 그리스 본토·펠로폰네소스를 잇는 관문', tag_en: 'REAL SETTING — the land bridge linking mainland Greece and the Peloponnese', travelTip: '코린토스 운하 전망대에서 조망 가능.', travelTip_en: 'Viewable from the Corinth Canal observation point.' },
  { id: 'real_lake_avernus', order: 37, modernName: '아베르노 호수 (이탈리아 나폴리 인근)', lat: 40.8358, lng: 14.0592, description: '고대 로마 전통(베르길리우스의 《아이네이스》)에서 저승으로 통하는 또 다른 입구로 여겨진 화산 호수. 오디세이 신화 전승과도 자주 겹쳐 언급되는 지중해의 대표적 \'저승문\' 전설지다.', description_en: 'A volcanic lake regarded in Roman tradition (Virgil\'s Aeneid) as another entrance to the underworld — a Mediterranean \'gateway to Hades\' legend often mentioned alongside the Odyssey tradition.', tag: '실제 신화 속 지명 — 저승 입구 전설이 겹치는 화산호', tag_en: 'REAL SETTING — legendary underworld entrance, overlapping the Odyssey tradition', travelTip: '나폴리에서 근교 열차로 접근.', travelTip_en: 'Reachable by regional train from Naples.' },
  { id: 'real_delphi', order: 38, modernName: '델포이 유적 (그리스 포키스)', lat: 38.4824, lng: 22.501, description: '그리스 신화 세계관 전체를 지탱하는 아폴론의 신탁소. 오디세이 서사에는 직접 등장하지 않지만, 텔레마코스와 오디세우스가 의지하는 \'예언\'이라는 모티프 전체가 이 신탁 전통과 맞닿아 있다.', description_en: 'The oracle of Apollo underpinning the whole Greek mythological worldview. It does not appear directly in the Odyssey, but the entire motif of prophecy that Telemachus and Odysseus rely on is rooted in this oracular tradition.', tag: '실제 신화 속 지명 — 그리스 신화 예언 전통의 중심지', tag_en: 'REAL SETTING — the heart of Greek prophetic tradition', travelTip: '아테네에서 버스로 약 3시간.', travelTip_en: 'About a 3-hour bus ride from Athens.' },
  { id: 'real_mount_olympus', order: 39, modernName: '올림포스 산 (그리스 테살리아·마케도니아)', lat: 40.0853, lng: 22.3584, description: '제우스·포세이돈·아테나 등 영화에 언급되는 신들이 산다고 여겨진 그리스 최고봉. \'제우스의 율법\'이라는 대사로 영화 내내 그 존재감이 언급된다.', description_en: 'Greece\'s highest peak, believed to be home to the gods invoked throughout the film — Zeus, Poseidon, Athena — whose \'law of Zeus\' is referenced repeatedly in the story.', tag: '실제 신화 속 지명 — 그리스 신들의 거처', tag_en: 'REAL SETTING — the mythological home of the Greek gods', travelTip: '리토호로 마을에서 등반 시작.', travelTip_en: 'Ascents typically begin from the village of Litochoro.' },
  { id: 'real_acropolis_athens', order: 40, modernName: '아테네 아크로폴리스 (그리스)', lat: 37.9715, lng: 23.7267, description: '영화 속 지혜와 전략의 여신 아테나를 상징하는 실제 현대 도시의 성소. 여신 아테나의 이름을 딴 도시 아테네의 파르테논 신전이 여기 서 있다.', description_en: 'The real sanctuary most emblematic of the goddess Athena — protagonist of the film\'s divine subplot — crowned by the Parthenon in the city that bears her name.', tag: '실제 신화 속 지명 — 아테나 여신을 상징하는 실제 성소', tag_en: 'REAL SETTING — the real sanctuary of the goddess Athena', travelTip: '아테네 시내에서 도보·지하철로 접근.', travelTip_en: 'Accessible on foot or by metro within central Athens.' },
  { id: 'real_necromanteion', order: 41, modernName: '네크로만테이온 (그리스 에피루스, 아케론강)', lat: 39.254, lng: 20.554, description: '고대 그리스인들이 실제로 죽은 자와 대화하기 위해 순례했던 \'저승의 신탁소\' 유적. 아케론 강가에 세워져 있으며, 오디세우스가 망자를 소환해 예언을 듣는 영화 속 에피소드의 원형이 되는 실제 종교 유적이다.', description_en: 'The real \'Oracle of the Dead\' where ancient Greeks genuinely made pilgrimages to consult the deceased, sited on the Acheron River — the historical religious site behind the film\'s episode of Odysseus summoning the dead for prophecy.', tag: '실제 신화 속 지명 — 실제 \'저승의 신탁소\' 유적', tag_en: 'REAL SETTING — the real \'Oracle of the Dead\' site', travelTip: '그리스 서부 에피루스, 파르가 인근.', travelTip_en: 'In western Greek Epirus, near Parga.' },
  { id: 'real_thrinacia_sicily', order: 42, modernName: '시칠리아 (전통적 \'트리나키아\' 비정지)', lat: 37.599, lng: 14.0154, description: '\'세 개의 곶\'이라는 뜻의 고대 지명 트리나크리아에서 유래한 시칠리아의 옛 이름. 헬리오스(태양신)의 신성한 소 떼가 있던 섬 \'트리나키아\'로 전통적으로 비정되어 왔으며, 오늘날 시칠리아 국기에도 그 흔적(트리스켈리온 문양)이 남아 있다.', description_en: 'Sicily\'s ancient name Trinacria (\'three capes\') is the traditional root of \'Thrinacia\', the island of the sun god Helios\'s sacred cattle — a link still visible today in the triskelion emblem on Sicily\'s flag.', tag: '실제 신화 속 지명 — 헬리오스의 섬 \'트리나키아\'의 전통적 비정지', tag_en: 'REAL SETTING — traditional identification of Helios\'s island \'Thrinacia\'', travelTip: '시칠리아 전역, 특히 주도 팔레르모의 깃발 문양에서 확인 가능.', travelTip_en: 'Across Sicily; visible on the regional flag\'s triskelion in Palermo.' },
  { id: 'real_cape_sounion', order: 43, modernName: '수니온곶 포세이돈 신전 (그리스 아티카)', lat: 37.6503, lng: 24.0233, description: '영화 내내 오디세우스를 벌하는 신, 포세이돈에게 실제로 바쳐진 고대 신전이 서 있는 아티카 반도 최남단의 곶. 에게해로 지는 해를 바라보는 절경으로 유명하다.', description_en: 'The southernmost tip of Attica, home to a real ancient temple actually dedicated to Poseidon — the god who punishes Odysseus throughout the film. Famous for its sunset views over the Aegean.', tag: '실제 신화 속 지명 — 포세이돈에게 실제로 봉헌된 신전', tag_en: 'REAL SETTING — temple genuinely dedicated to Poseidon', travelTip: '아테네에서 남쪽으로 약 70km, 해안도로 드라이브 코스로도 유명.', travelTip_en: 'About 45 miles south of Athens; a famous coastal scenic drive.' },
  { id: 'ithaca_banquet_hall', order: 44, modernName: '이타카 왕궁 연회장', description: '음유시인이 오디세우스의 트로이 전쟁 영웅담을 노래하는 영화의 첫 시퀀스 무대이자, 안티노오스를 비롯한 구혼자들이 매일 밤 눌러앉아 페넬로페에게 구애하는 공간.', description_en: 'The setting of the film\'s opening sequence, where the bard sings of Odysseus\'s Trojan War exploits, and where Antinous and the suitors camp out nightly to court Penelope.', tag: '가상 스토리 장소 — 이타카 궁 연회장', tag_en: 'STORY SETTING — Ithaca palace banquet hall', travelTip: '', travelTip_en: '' },
  { id: 'trojan_horse_field', order: 45, modernName: '트로이 목마 앞 벌판', description: '이타카 병사 시논이 트로이 병사에게 붙잡혀 \'아테나에게 바치는 제물\'이라고 목마의 정체를 속이는 영화 도입부의 무대.', description_en: 'Where Ithacan soldier Sinon is captured by Trojan troops and convinces them the horse is \'an offering to Athena\' — the film\'s opening deception.', tag: '가상 스토리 장소 — 트로이 목마 발견 현장', tag_en: 'STORY SETTING — where the Trojans first find the wooden horse', travelTip: '', travelTip_en: '' },
  { id: 'penelope_weaving_room', order: 46, modernName: '페넬로페의 내실 (수의를 짜는 방)', description: '시아버지 라에르테스의 수의를 완성하기 전엔 재혼할 수 없다는 핑계로, 페넬로페가 낮에 짠 것을 밤마다 몰래 풀며 구혼자들의 청혼을 미루는 방.', description_en: 'The room where Penelope weaves Laertes\'s burial shroud by day and secretly unravels it by night, using the unfinished task as an excuse to stall the suitors.', tag: '가상 스토리 장소 — 페넬로페의 수의 방', tag_en: 'STORY SETTING — Penelope\'s weaving chamber', travelTip: '', travelTip_en: '' },
  { id: 'telemachus_training_ground', order: 47, modernName: '텔레마코스의 검술 수련장', description: '눈이 멀어 돼지치기가 된 옛 심복 에우마이오스와 부관 멘토르에게 검술을 배우며 오디세우스의 사냥개 아르고스 이야기를 듣는 곳.', description_en: 'Where Telemachus trains in swordsmanship under the blinded former retainer Eumaeus and the steward Mentor, and first hears the story of Odysseus\'s dog Argos.', tag: '가상 스토리 장소 — 텔레마코스 수련 장면', tag_en: 'STORY SETTING — Telemachus\'s swordsmanship training scene', travelTip: '', travelTip_en: '' },
  { id: 'odysseus_boar_hunt', order: 48, modernName: '오디세우스의 멧돼지 사냥터', description: '젊은 텔레마코스가 회상 속에서 목격하는 오디세우스의 사냥 습관 — 사냥감에게 미리 활 시위 소리로 경고하는 \'공정한 싸움\'의 신념 — 이 드러나는 장소. 이때 입은 발목 상처가 훗날 유모 에우리클레이아가 오디세우스를 알아보는 단서(원작)와 이어지는 모티프이기도 하다.', description_en: 'Where young Telemachus, in flashback, witnesses Odysseus\'s hunting creed — always giving prey fair warning with a twang of the bowstring — and where he\'s wounded in the ankle, echoing the scar-recognition motif of the original epic.', tag: '가상 스토리 장소 — 오디세우스 사냥 회상 장면', tag_en: 'STORY SETTING — flashback of Odysseus\'s hunt', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_farewell_feast', order: 49, modernName: '이타카 궁 출정 전야 연회장', description: '오디세우스가 활 시위를 당겨 소리를 내고 12개의 도끼 사이로 화살을 날리는 묘기를 선보이는, 전쟁 전 마지막 평화로운 연회 장면의 배경.', description_en: 'The setting of the last peaceful feast before the war, where Odysseus performs his signature trick — firing an arrow through the gap between twelve axes.', tag: '가상 스토리 장소 — 출정 전야 연회 (도끼 사이 화살 묘기)', tag_en: 'STORY SETTING — the pre-war feast and the axe-shot trick', travelTip: '', travelTip_en: '' },
  { id: 'odysseus_penelope_bedroom', order: 50, modernName: '오디세우스와 페넬로페의 침소', description: '출정 전날 밤, 오디세우스가 전쟁의 진짜 이유(아가멤논의 무역로 야심)를 고백하고 페넬로페가 아테나 문양의 금 브로치를 건네는 장면의 배경.', description_en: 'Where, the night before departure, Odysseus confesses the war\'s real cause — Agamemnon\'s ambition for trade routes — and Penelope gives him the gold Athena brooch.', tag: '가상 스토리 장소 — 출정 전야 침소 대화', tag_en: 'STORY SETTING — the eve-of-war bedroom conversation', travelTip: '', travelTip_en: '' },
  { id: 'conscription_lottery_site', order: 51, modernName: '트로이 전쟁 징병 추첨 현장', description: '시논이 뽑은 \'면제\' 표를 안티노오스가 가로채 자신의 징집 표와 바꿔치기하는, 훗날 시논의 죽음과 아버지의 아사로 이어지는 비극의 발단이 된 곳.', description_en: 'Where Antinous swaps his conscription lot for Sinon\'s exemption — the origin of the tragedy that leads to Sinon\'s death and his father\'s starvation.', tag: '가상 스토리 장소 — 징병 추첨 현장', tag_en: 'STORY SETTING — the conscription lottery', travelTip: '', travelTip_en: '' },
  { id: 'sparta_wedding_feast', order: 52, modernName: '스파르타 궁 헤르미오네 결혼 축하연', description: '메넬라오스와 헬레네의 딸 헤르미오네의 결혼을 축하하는 연회 자리. 마침 이곳을 예고 없이 찾아온 텔레마코스가 메넬라오스 옆자리에 앉아 트로이 목마 작전의 전말을 직접 듣는다.', description_en: 'The wedding feast for Menelaus and Helen\'s daughter Hermione — where the unannounced Telemachus is seated beside Menelaus and hears the full story of the Trojan Horse operation firsthand.', tag: '가상 스토리 장소 — 헤르미오네 결혼 연회', tag_en: 'STORY SETTING — Hermione\'s wedding feast', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_argos_incident', order: 53, modernName: '이타카 궁 아르고스 학대 사건 현장', description: '늙은 사냥개 아르고스를 구혼자들이 발로 건드리며 괴롭히자 에우마이오스가 간청하고, 이를 말리던 텔레마코스가 안티노오스의 친구 폴리부스에게 제압당하는 장면의 무대.', description_en: 'Where the suitors torment the aging dog Argos, prompting Eumaeus\'s plea and Telemachus\'s intervention — only for him to be overpowered by Antinous\'s friend Polybus.', tag: '가상 스토리 장소 — 아르고스 학대·텔레마코스 봉변 현장', tag_en: 'STORY SETTING — the Argos incident and Telemachus\'s humiliation', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_secret_departure', order: 54, modernName: '이타카 왕궁 비밀 출항 지점', description: '구혼자들의 암살 위협을 피하기 위해 텔레마코스가 스파르타로 몰래 준비해 떠나는 은밀한 출항 지점.', description_en: 'The secret point from which Telemachus quietly departs for Sparta, avoiding the suitors who would kill him en route.', tag: '가상 스토리 장소 — 텔레마코스 비밀 출항지', tag_en: 'STORY SETTING — Telemachus\'s secret departure point', travelTip: '', travelTip_en: '' },
  { id: 'calypso_awakening_site', order: 55, modernName: '칼립소의 섬 — 오디세우스가 깨어나는 곳', description: '기억을 잃은 오디세우스가 \'돌아갈 집이 있다\'는 사실을 어렴풋이 되찾기 시작하며 칼립소와 대화를 나누는, 영화의 현재 시점 시작 지점.', description_en: 'Where the memory-wiped Odysseus begins to recall that he has a home to return to, and speaks with Calypso — the film\'s framing present-day starting point.', tag: '가상 스토리 장소 — 오디세우스가 깨어나는 곳(오기기아)', tag_en: 'STORY SETTING — where Odysseus first awakens on Ogygia', travelTip: '', travelTip_en: '' },
  { id: 'ismarus_raid_site', order: 56, modernName: '이스마로스 약탈 현장', description: '트로이를 떠난 오디세우스 일행이 처음 들른 키코네스족의 해안 마을. 노인이 \'바다 민족\'으로 오인해 도망쳤다가 이들에게 앞으로의 항로에 끔찍한 것들이 기다린다고 경고하지만 묵살당한다.', description_en: 'The first stop after Troy — a Cicones\' coastal village. An elder who mistakes the crew for the \'Sea People\' warns of horrors ahead on their route, but is ignored.', tag: '가상 스토리 장소 — 이스마로스 약탈·노인의 경고', tag_en: 'STORY SETTING — the Ismarus raid and the elder\'s warning', travelTip: '', travelTip_en: '' },
  { id: 'polyphemus_cave_interior', order: 57, modernName: '폴리페무스의 동굴 내부 (극중 감금 장소)', description: '양을 쫓아 들어갔다가 거대한 외눈박이 폴리페무스에게 갇히는 동굴. 병사들이 잡아먹히고, 오디세우스가 불에 달군 나무창으로 그의 눈을 찔러 실명시키는 영화 최고의 공포 시퀀스 무대.', description_en: 'The cave the crew enters chasing a stray sheep, only to be trapped by the giant one-eyed Polyphemus — the site of the film\'s most acclaimed horror sequence, where Odysseus blinds him with a fire-hardened stake.', tag: '가상 스토리 장소 — 폴리페무스와의 사투', tag_en: 'STORY SETTING — the fight with Polyphemus', travelTip: '', travelTip_en: '' },
  { id: 'polyphemus_cave_exit', order: 58, modernName: '폴리페무스의 동굴 입구 (양떼 탈출 지점)', description: '실명한 폴리페무스가 양의 등을 만지며 탈출을 막으려 하자, 병사들이 지푸라기로 양털 촉감을 흉내 내 몰래 빠져나가는 극적인 탈출 지점.', description_en: 'Where the blinded Polyphemus feels each sheep\'s back to stop any escape, and the crew tricks him by disguising themselves under fleece.', tag: '가상 스토리 장소 — 양떼 위장 탈출 지점', tag_en: 'STORY SETTING — the sheep-disguise escape', travelTip: '', travelTip_en: '' },
  { id: 'laestrygonian_shore', order: 59, modernName: '라이스트뤼고네스 섬 해안', description: '오디세우스 일행이 거인족 아이와 처음 마주친 뒤, 아이가 소리 질러 갑옷을 두른 거인 전사들을 불러 모으는 해안.', description_en: 'The shore where the crew first encounters a giant child, whose scream summons the armoured Laestrygonian warriors.', tag: '가상 스토리 장소 — 라이스트뤼고네스 첫 조우', tag_en: 'STORY SETTING — first encounter with the Laestrygonians', travelTip: '', travelTip_en: '' },
  { id: 'laestrygonian_harbor_massacre', order: 60, modernName: '라이스트뤼고네스족의 항구 학살 현장', description: '거인들이 3척의 배 중 2척을 좌우로 흔들어 침몰시키고 생존자들을 학살하는, 오디세우스의 함대가 사실상 전멸하는 참극의 현장.', description_en: 'Where the giants capsize two of three ships and slaughter the survivors — the massacre that effectively wipes out Odysseus\'s fleet.', tag: '가상 스토리 장소 — 함대 전멸 참극 현장', tag_en: 'STORY SETTING — the massacre that destroys the fleet', travelTip: '', travelTip_en: '' },
  { id: 'circe_house', order: 61, modernName: '키르케의 집', description: '노루인 줄 알고 쐈던 화살이 실은 사람을 맞혔음을 깨달으며 밝혀지는 마녀 키르케의 거처. 환대인 척 차려낸 음식을 먹은 병사들이 돼지로 변한다.', description_en: 'The witch Circe\'s home, discovered when a supposed deer turns out to be a transformed man. Soldiers who eat her hospitable-seeming meal are turned into pigs.', tag: '가상 스토리 장소 — 병사들이 돼지로 변한 곳', tag_en: 'STORY SETTING — where the crew are turned into pigs', travelTip: '', travelTip_en: '' },
  { id: 'circe_sister_hostage', order: 62, modernName: '키르케의 집 — 인질극 현장', description: '오디세우스가 새로 변한 키르케의 누이를 인질로 삼아 대치하며, 병사들을 원래대로 되돌려 달라고 요구하는 긴장의 장면.', description_en: 'Where Odysseus takes Circe\'s bird-transformed sister hostage, demanding his men be restored to human form.', tag: '가상 스토리 장소 — 키르케와의 대치 장면', tag_en: 'STORY SETTING — the standoff with Circe', travelTip: '', travelTip_en: '' },
  { id: 'dead_shore_north', order: 63, modernName: '망자들의 해변 (극중 저승 문턱)', description: '얼음의 강과 불의 강이 만나는 먼 북쪽의 해변. 오디세우스가 양 두 마리를 제물로 바쳐 망자들을 불러내고, 시논·아가멤논·테이레시아스를 차례로 만난다.', description_en: 'A far northern shore where the river of fire meets the river of ice. Odysseus sacrifices two sheep to summon the dead, meeting Sinon, Agamemnon, and Tiresias in turn.', tag: '가상 스토리 장소 — 망자 소환 의식(저승 문턱)', tag_en: 'STORY SETTING — the ritual summoning of the dead', travelTip: '', travelTip_en: '' },
  { id: 'sirens_waters', order: 64, modernName: '세이렌의 해역', description: '선원들이 밀랍으로 귀를 막고 오디세우스만 돛대에 몸을 묶은 채 노래를 들으며 지나가는 해역. 병사 한 명(윌 윤 리 역)이 유혹을 이기지 못해 바다로 뛰어들어 사라진다.', description_en: 'The waters the crew crosses with wax-sealed ears while Odysseus, bound to the mast, alone hears the Sirens\' song — one man succumbs and vanishes into the sea.', tag: '가상 스토리 장소 — 세이렌의 유혹', tag_en: 'STORY SETTING — the temptation of the Sirens', travelTip: '', travelTip_en: '' },
  { id: 'scylla_charybdis_channel', order: 65, modernName: '스킬라와 카리브디스의 해협', description: '카리브디스의 소용돌이를 급류 추진력 삼아 우회하려던 오디세우스의 의도와 달리, 병사들이 스스로 방향을 꺾어 스킬라의 협곡으로 들어서며 6명을 잃는 곳.', description_en: 'Where, despite Odysseus\'s plan to use Charybdis\'s whirlpool as a slingshot, the panicked crew steers into Scylla\'s channel instead, losing six men.', tag: '가상 스토리 장소 — 스킬라·카리브디스 통과 장면', tag_en: 'STORY SETTING — passing between Scylla and Charybdis', travelTip: '', travelTip_en: '' },
  { id: 'helios_island', order: 66, modernName: '헬리오스(태양신)의 섬', description: '지친 병사들이 정박을 요청해 상륙한 섬. 금기로 정해진 태양신의 소 350마리를 절대 먹지 않기로 맹세했으나, 결국 굶주림을 못 이겨 금기를 어기고 만다.', description_en: 'The island where the exhausted crew, sworn never to touch the sun god\'s 350 sacred cattle, finally breaks the taboo out of starvation.', tag: '가상 스토리 장소 — 태양신의 소를 잡아먹은 곳', tag_en: 'STORY SETTING — where the crew eats the forbidden sacred cattle', travelTip: '', travelTip_en: '' },
  { id: 'final_shipwreck_site', order: 67, modernName: '최후의 난파 지점', description: '금기를 어긴 대가로 제우스의 폭풍을 만나 배가 두 동강 나며 병사 전원이 죽고 오디세우스만 홀로 표류하게 되는 지점.', description_en: 'Where Zeus\'s storm splits the ship in two as punishment, killing every man but Odysseus, who alone survives adrift.', tag: '가상 스토리 장소 — 함대 전멸·오디세우스 단독 표류 시작점', tag_en: 'STORY SETTING — the wreck that leaves Odysseus alone at sea', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_shore_awakening', order: 68, modernName: '이타카 해안 (아테나와의 재회)', description: '뗏목으로 표류하던 오디세우스가 정신을 차려보니 아테나가 옆에 앉아 있고, 이곳이 바로 그리던 고향 이타카임을 알게 되는 장소.', description_en: 'Where the drifting Odysseus wakes to find Athena beside him — and learns this shore is Ithaca itself, his long-sought home.', tag: '가상 스토리 장소 — 오디세우스의 이타카 귀환 지점', tag_en: 'STORY SETTING — Odysseus\'s homecoming shore', travelTip: '', travelTip_en: '' },
  { id: 'eumaeus_pigfarm_ithaca', order: 69, modernName: '에우마이오스의 돼지우리 (극중 재회 장소)', description: '거지로 변장한 오디세우스가 옛 심복 에우마이오스와 재회하지만, 안티노오스의 사주를 받은 도적들이 이미 그의 아들들을 죽이고 텔레마코스를 노린다는 소식을 듣는 장소.', description_en: 'Where the disguised Odysseus reunites with Eumaeus, only to learn that Antinous\'s hired brigands have already killed his sons and are hunting Telemachus.', tag: '가상 스토리 장소 — 오디세우스·에우마이오스 재회', tag_en: 'STORY SETTING — Odysseus\'s reunion with Eumaeus', travelTip: '', travelTip_en: '' },
  { id: 'telemachus_ambush_route', order: 70, modernName: '텔레마코스 암살 매복로', description: '폴리부스의 부관이 이끄는 도적들이 스파르타에서 돌아오는 텔레마코스를 노리고 매복한 귀환 항로.', description_en: 'The return route where brigands led by Polybus\'s lieutenant lie in ambush for Telemachus on his way back from Sparta.', tag: '가상 스토리 장소 — 텔레마코스 암살 시도 항로', tag_en: 'STORY SETTING — the ambush route on Telemachus\'s return', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_throne_room_battle', order: 71, modernName: '이타카 궁 알현실 (구혼자 최후 결전)', description: '정체를 드러낸 오디세우스가 활 시합을 통해 무장하고, 텔레마코스와 함께 구혼자 전원을 처단하는 영화의 클라이맥스 무대.', description_en: 'The film\'s climax: Odysseus, revealed, arms himself through the bow contest and, with Telemachus, cuts down every suitor.', tag: '가상 스토리 장소 — 구혼자 처단 최후 결전', tag_en: 'STORY SETTING — the climactic slaughter of the suitors', travelTip: '', travelTip_en: '' },
  { id: 'axe_bow_contest_site', order: 72, modernName: '열두 자루 도끼 사이 활 시합 현장', description: '오직 오디세우스만 걸 수 있었던 활의 시위를 다시 당겨 열두 개의 도끼 사이로 화살을 쏘아 보내며 자신의 정체를 증명하는 결말부의 시험장.', description_en: 'The site of the film\'s identity-proving trial: only Odysseus can string his old bow and shoot an arrow through the gap of twelve axes.', tag: '가상 스토리 장소 — 활 시합(정체 증명)', tag_en: 'STORY SETTING — the bow contest that proves Odysseus\'s identity', travelTip: '', travelTip_en: '' },
  { id: 'penelope_reunion_chamber', order: 73, modernName: '페넬로페의 재회 확인의 방', description: '오랜 세월 끝에 재회한 부부가 둘만 아는 침상의 비밀로 서로의 정체를 최종 확인하는, 원작에서 가장 유명한 장면 중 하나가 재현되는 방.', description_en: 'Where the long-reunited couple confirm each other\'s identity through a secret only they know about their marriage bed — one of the epic\'s most famous scenes, recreated here.', tag: '가상 스토리 장소 — 부부 재회 확인 장면', tag_en: 'STORY SETTING — the recognition scene between Odysseus and Penelope', travelTip: '', travelTip_en: '' },
  { id: 'troy_wooden_horse_workshop', order: 74, modernName: '트로이 목마 제작 현장', description: '오디세우스의 계략으로 정예 부대를 숨긴 거대한 목마가 설계·제작된, 트로이 함락 작전의 시발점.', description_en: 'Where the giant wooden horse concealing an elite strike force is designed and built, the opening move of Odysseus\'s plan to take Troy.', tag: '가상 스토리 장소 — 트로이 목마 설계·제작 현장', tag_en: 'STORY SETTING — where the Trojan Horse is designed and built', travelTip: '', travelTip_en: '' },
  { id: 'troy_horse_interior', order: 75, modernName: '트로이 목마 내부', description: '물에 반쯤 잠긴 목마 속에서 병사들이 숨죽여 대기하다 익사 위기와 발각 위기를 겪으며 버티는, 트로이 함락 작전의 긴장감 넘치는 무대.', description_en: 'Inside the half-submerged horse, soldiers wait in tense silence, facing near-drowning and near-discovery before the operation succeeds.', tag: '가상 스토리 장소 — 목마 속 병사들의 잠복', tag_en: 'STORY SETTING — soldiers hiding inside the Trojan Horse', travelTip: '', travelTip_en: '' },
  { id: 'troy_city_gates_fall', order: 76, modernName: '트로이 성문 함락 현장', description: '목마 속 정예 부대가 성문을 열어 그리스 연합군을 성 안으로 돌격시키며 트로이가 함락되는 전쟁의 결정적 순간.', description_en: 'The decisive moment of the war: the elite force inside the horse opens the gates, letting the Greek army storm the city.', tag: '가상 스토리 장소 — 트로이 함락의 결정적 순간', tag_en: 'STORY SETTING — the fall of Troy', travelTip: '', travelTip_en: '' },
  { id: 'athena_temple_troy', order: 77, modernName: '아테나 신전 (트로이)', description: '목마를 \'아테나에게 바치는 제물\'로 위장하는 명분이 된, 양쪽 진영 모두가 섬기던 여신 아테나의 신전.', description_en: 'The temple of Athena — a goddess worshipped by both warring sides — that provides the pretext for smuggling in the wooden horse as \'an offering\'.', tag: '가상 스토리 장소 — 트로이의 아테나 신전', tag_en: 'STORY SETTING — the Temple of Athena at Troy', travelTip: '', travelTip_en: '' },
  { id: 'mycenae_agamemnon_murder', order: 78, modernName: '미케네 궁 — 아가멤논 살해 현장', description: '성대히 귀향한 아가멤논이 딸 이피게네이아를 제물로 바친 것을 원망한 아내 클리타임네스트라와 그 정부 아이기스토스에게 살해당하는 장소(회상).', description_en: 'Where the triumphantly returning Agamemnon is murdered by his wife Clytemnestra and her lover Aegisthus, in revenge for the sacrifice of their daughter Iphigenia.', tag: '가상 스토리 장소 — 아가멤논 살해 현장(회상)', tag_en: 'STORY SETTING — the murder of Agamemnon (flashback)', travelTip: '', travelTip_en: '' },
  { id: 'orestes_revenge_site', order: 79, modernName: '오레스테스의 복수 현장 (원작 언급)', description: '아가멤논과 클리타임네스트라의 아들 오레스테스가 아버지의 원수를 갚기 위해 어머니와 아이기스토스를 살해하는, 메넬라오스의 대사로 전해지는 사건의 무대.', description_en: 'Where Orestes, son of Agamemnon and Clytemnestra, avenges his father by killing his mother and Aegisthus — an event relayed through Menelaus\'s dialogue.', tag: '가상 스토리 장소 — 오레스테스의 복수(언급된 사건)', tag_en: 'STORY SETTING — Orestes\'s revenge (referenced offscreen)', travelTip: '', travelTip_en: '' },
  { id: 'aulis_sacrifice_site', order: 80, modernName: '아울리스 — 이피게네이아 제물 의식 현장', description: '아가멤논이 트로이 원정의 순풍을 얻기 위해 어린 딸 이피게네이아를 제물로 바쳤다는, 오디세우스의 대사를 통해 전해지는 트로이 전쟁 발발 직전의 사건 현장.', description_en: 'The site, relayed through Odysseus\'s dialogue, where Agamemnon sacrifices his young daughter Iphigenia for favourable winds to Troy — just before the war begins.', tag: '가상 스토리 장소 — 이피게네이아 제물 의식(언급된 사건)', tag_en: 'STORY SETTING — the sacrifice of Iphigenia (referenced)', travelTip: '', travelTip_en: '' },
  { id: 'pylos_road_bandit', order: 81, modernName: '파일로스행 여정 중 도적 조우 지점', description: '한 걸인에게서 스파르타에 가면 오디세우스의 소식을 알 수 있다는 조언을 들은 텔레마코스가 여정 중 마주치는 파일로스의 강도(원작 인용 캐릭터)와의 접점.', description_en: 'Where Telemachus, tipped off by a beggar that news of Odysseus awaits in Sparta, crosses paths with a bandit from Pylos.', tag: '가상 스토리 장소 — 텔레마코스 여정 중 도적 조우', tag_en: 'STORY SETTING — Telemachus\'s encounter with a bandit en route', travelTip: '', travelTip_en: '' },
  { id: 'antinous_manor_seduction', order: 82, modernName: '안티노오스의 저택 (페넬로페 유혹 장면)', description: '안티노오스가 페넬로페에게 수의를 밤마다 풀고 있다는 사실을 추궁하며 유혹하다, 텔레마코스에 대한 실언으로 냉대받는 장면의 배경.', description_en: 'Where Antinous confronts Penelope over unravelling the shroud each night and tries to seduce her, only to slip up about Telemachus and be coldly rebuffed.', tag: '가상 스토리 장소 — 안티노오스의 유혹·실언 장면', tag_en: 'STORY SETTING — Antinous\'s failed seduction attempt', travelTip: '', travelTip_en: '' },
  { id: 'melantho_antinous_tryst', order: 83, modernName: '멜란토와 안티노오스의 밀회 장소', description: '시녀 멜란토가 안티노오스와 내통하며 페넬로페의 비밀(수의를 풀고 있다는 사실, 텔레마코스의 출항)을 누설하는, 에우마이오스가 몰래 목격하는 장소.', description_en: 'Where the maid Melantho secretly trysts with Antinous, leaking Penelope\'s secrets — and where Eumaeus, hidden, overhears everything.', tag: '가상 스토리 장소 — 멜란토의 내통 장면', tag_en: 'STORY SETTING — Melantho\'s secret collusion with Antinous', travelTip: '', travelTip_en: '' },
  { id: 'odysseus_penelope_bow_gift', order: 84, modernName: '페넬로페가 활을 건네는 장면의 배경', description: '왕위를 넘기라 압박하는 원로들 앞에서, 페넬로페가 텔레마코스에게 오디세우스의 활을 건네며 시위를 걸어보라 시험하는 장면의 무대.', description_en: 'Where, pressured by elders to name an heir, Penelope hands Telemachus Odysseus\'s bow and challenges him to string it.', tag: '가상 스토리 장소 — 활 시위 시험 장면', tag_en: 'STORY SETTING — Penelope tests Telemachus with Odysseus\'s bow', travelTip: '', travelTip_en: '' },
  { id: 'lotus_flower_grove', order: 85, modernName: '로터스 나무 숲 (오기기아)', description: '칼립소가 오디세우스에게 계속 먹여 기억을 지운 로터스 나무 꽃이 자라는, 치유와 망각이 공존하는 숲.', description_en: 'Where the lotus flowers Calypso keeps feeding Odysseus — erasing his memory even as they heal him — grow on Ogygia.', tag: '가상 스토리 장소 — 로터스 나무 숲', tag_en: 'STORY SETTING — the lotus-flower grove', travelTip: '', travelTip_en: '' },
  { id: 'calypso_raft_beach', order: 86, modernName: '칼립소의 섬 — 뗏목을 만든 해변', description: '기억을 잃은 와중에도 무의식중에 나무를 모아 뗏목을 만들던 오디세우스가, 진실을 알게 된 뒤 마침내 완성해 바다로 떠나는 해변.', description_en: 'The beach where, even memory-wiped, Odysseus unconsciously gathers driftwood for a raft — which he finally completes and sails from once the truth is restored.', tag: '가상 스토리 장소 — 뗏목 완성·출항 지점', tag_en: 'STORY SETTING — where Odysseus builds and launches his raft', travelTip: '', travelTip_en: '' },
  { id: 'underworld_unburied_shore', order: 87, modernName: '저승 — 묻히지 못한 병사들의 해변', description: '매장되지 못한 무수한 병사들의 망령이 오디세우스 일행을 원망하며 뒤쫓다, 해변에서 더는 나아가지 못하고 멈춰서는 저승의 경계.', description_en: 'Where the countless unburied dead, resentful of Odysseus and his men, pursue them before halting at the shoreline — the boundary of the underworld.', tag: '가상 스토리 장소 — 묻히지 못한 병사들의 저승 경계', tag_en: 'STORY SETTING — the boundary where the unburied dead are left behind', travelTip: '', travelTip_en: '' },
  { id: 'phaeacia_court_omitted', order: 88, modernName: '파이아케스인의 궁전 (원작에만 등장, 영화에서 생략)', description: '호메로스 원작에서는 오디세우스가 스케리아의 알키노오스 왕과 아레테 왕비, 공주 나우시카의 도움으로 마지막 귀향길에 오르지만, 이 영화는 뗏목이 곧장 이타카 해안에 닿는 것으로 각색해 이 에피소드 전체를 생략했다.', description_en: 'In Homer\'s original, Odysseus reaches home with help from King Alcinous, Queen Arete, and Princess Nausicaa of Scheria — but this film cuts the entire episode, having the raft wash up directly on Ithaca instead.', tag: '가상 스토리 장소 — 원작 파이아케스 에피소드(영화에서 생략)', tag_en: 'STORY SETTING — Homer\'s Phaeacian episode, cut from this film', travelTip: '', travelTip_en: '' },
  { id: 'nausicaa_beach_meeting', order: 89, modernName: '나우시카와의 해변 만남 (원작에만 등장)', description: '호메로스 원작에서 난파해 표류하던 오디세우스가 빨래하러 나온 공주 나우시카와 처음 마주치는 유명한 장면. 이 영화 각색에는 등장하지 않는다.', description_en: 'Homer\'s famous scene where the shipwrecked Odysseus first meets Princess Nausicaa, out doing laundry — not present in this film\'s adaptation.', tag: '가상 스토리 장소 — 원작 나우시카 조우 장면(영화에서 생략)', tag_en: 'STORY SETTING — Homer\'s Nausicaa scene, cut from this film', travelTip: '', travelTip_en: '' },
  { id: 'ithaca_council_hall', order: 90, modernName: '이타카 원로회의실', description: '오디세우스의 부재가 길어지며 원로들이 후계자 문제를 두고 텔레마코스와 페넬로페를 압박하는 회의 장소.', description_en: 'Where the council of elders pressures Telemachus and Penelope over the succession question as Odysseus\'s absence stretches on.', tag: '가상 스토리 장소 — 원로회의 압박 장면', tag_en: 'STORY SETTING — the elders\' council pressuring the royal family', travelTip: '', travelTip_en: '' },
  { id: 'beggar_disguise_alley', order: 91, modernName: '거지로 변장한 오디세우스가 괄시받는 골목', description: '아가멤논의 조언대로 걸인으로 위장해 은밀히 상황을 살피던 오디세우스가 구혼자들에게 함부로 대접받는, 원작에서 유명한 굴욕의 시퀀스가 재현되는 공간.', description_en: 'Following Agamemnon\'s advice to scout in disguise, Odysseus endures mistreatment from the suitors as a beggar — recreating one of the epic\'s most famous scenes of humiliation.', tag: '가상 스토리 장소 — 거지 변장 굴욕 장면', tag_en: 'STORY SETTING — Odysseus mistreated in beggar\'s disguise', travelTip: '', travelTip_en: '' },
  { id: 'odyssey_ending_departure', order: 92, modernName: '결말 — 텔레마코스에게 왕위를 넘기고 서쪽으로 떠나는 항구', description: '구혼자들을 처단한 뒤, 오디세우스는 텔레마코스에게 왕위를 넘기고 페넬로페와 함께 통치를 내려놓은 채 서쪽 바다로 항해를 떠난다. 불타는 트로이 목마의 이미지가 겹쳐지며, 트로이 전쟁의 죄책과 새 세대로의 이양이라는 주제를 매듭짓는 영화의 마지막 장소.', description_en: 'After the suitors fall, Odysseus hands the throne to Telemachus and sails west with Penelope, leaving rule behind. The image of the burning Trojan Horse overlays the scene, closing the film\'s themes of war guilt and generational succession.', tag: '가상 스토리 장소 — 결말부 서쪽 항해 출항지', tag_en: 'STORY SETTING — the final voyage west, closing the film', travelTip: '', travelTip_en: '' },
  { id: 'menelaus_hunting_ground', order: 93, modernName: '스파르타 사냥터 (메넬라오스·텔레마코스)', description: '메넬라오스와 함께 사냥에 나선 텔레마코스가 아가멤논의 죽음과 오레스테스의 복수에 얽힌 비화를 전해 듣는 장소.', description_en: 'Where Telemachus, hunting alongside Menelaus, learns the story of Agamemnon\'s death and Orestes\'s revenge.', tag: '가상 스토리 장소 — 메넬라오스와의 사냥 대화', tag_en: 'STORY SETTING — the hunting-trip conversation with Menelaus', travelTip: '', travelTip_en: '' },
  { id: 'menelaus_farewell_gift', order: 94, modernName: '메넬라오스의 작별 선물 증정 장소', description: '스파르타를 떠나는 텔레마코스에게 메넬라오스가 방문 기념 선물을 건네고, 헬레네가 어머니 페넬로페에게 사과를 전해달라 부탁하는 이별의 장소.', description_en: 'Where Menelaus gives Telemachus a parting gift, and Helen asks him to relay an apology to his mother Penelope.', tag: '가상 스토리 장소 — 텔레마코스 스파르타 작별 장면', tag_en: 'STORY SETTING — Telemachus\'s farewell from Sparta', travelTip: '', travelTip_en: '' },
  { id: 'melantho_execution_site', order: 95, modernName: '이타카 궁 — 배신한 시녀들의 처형 장소', description: '구혼자들과 내통한 멜란토를 비롯한 배신자 시녀들이 오디세우스와 텔레마코스에 의해 처벌받는, 귀환 서사의 잔혹한 결말 중 하나가 벌어지는 장소.', description_en: 'Where Melantho and the other maids who colluded with the suitors face judgment from Odysseus and Telemachus — one of the homecoming\'s harshest reckonings.', tag: '가상 스토리 장소 — 배신 시녀 처벌 장면', tag_en: 'STORY SETTING — the punishment of the disloyal maids', travelTip: '', travelTip_en: '' },
  { id: 'melanthios_punishment_site', order: 96, modernName: '멜란티오스 처벌 현장', description: '구혼자들에게 가장 적극적으로 부역해 죄질이 가장 무거웠던 염소치기 멜란티오스가 처참한 최후를 맞는 장소.', description_en: 'Where the goatherd Melanthios — who armed the suitors most zealously and thus bore the heaviest guilt — meets his gruesome end.', tag: '가상 스토리 장소 — 멜란티오스 최후', tag_en: 'STORY SETTING — Melanthios\'s punishment', travelTip: '', travelTip_en: '' },
  { id: 'aeolia_wind_trial', order: 97, modernName: '아이올리아 — 포세이돈의 시험 장소', description: '원작에서는 바람의 신 아이올로스가 순풍이 담긴 자루를 건네는 곳이지만, 이 영화 각색에서는 포세이돈이 오디세우스 일행에게 가혹한 시련을 내리는 장소로 재해석됐다.', description_en: 'In Homer\'s original, the wind god Aeolus gives Odysseus a bag of favourable winds here — this adaptation reinterprets the island as a place where Poseidon inflicts brutal trials on the crew instead.', tag: '가상 스토리 장소 — 아이올리아의 시련(각색)', tag_en: 'STORY SETTING — Poseidon\'s trials at Aeolia (adapted from Homer)', travelTip: '', travelTip_en: '' },
  { id: 'helios_cattle_pasture', order: 98, modernName: '헬리오스의 350마리 신성한 소떼 방목지', description: '고대 그리스 태양력의 날수와 같은 350마리로 설정된 태양신의 소 떼가 풀을 뜯는 곳. 이 숫자는 병사들이 어긴 금기가 \'시간의 질서\' 자체에 대한 모독임을 상징한다.', description_en: 'Where the sun god\'s 350 sacred cattle graze — a number matching the days of the ancient Greek solar calendar, symbolising that the crew\'s taboo-breaking defies the very order of time.', tag: '가상 스토리 장소 — 헬리오스의 신성한 소떼', tag_en: 'STORY SETTING — Helios\'s 350 sacred cattle', travelTip: '', travelTip_en: '' },
  { id: 'storm_wreckage_drift', order: 99, modernName: '제우스의 폭풍 — 반파된 배의 표류 지점', description: '금기를 어긴 죄로 배가 정확히 둘로 갈라져, 오디세우스가 탄 쪽만 살아남고 나머지 병사들이 모두 죽는 표류의 시작점.', description_en: 'Where the ship splits exactly in two under Zeus\'s punishing storm — Odysseus\'s half survives, every other man perishes.', tag: '가상 스토리 장소 — 배가 두 동강 난 지점', tag_en: 'STORY SETTING — where the ship is split in two by the storm', travelTip: '', travelTip_en: '' },
  { id: 'calypso_truth_reveal_beach', order: 100, modernName: '칼립소가 진실을 밝히는 해변', description: '기억을 잃은 채로도 페넬로페의 금 브로치만은 놓지 않았던 오디세우스를 보고, 칼립소가 그를 붙잡을 수 없음을 깨달아 모든 진실을 알려주는 해변.', description_en: 'Where Calypso, seeing that Odysseus never let go of Penelope\'s gold brooch even memory-wiped, realizes she cannot keep him and reveals the whole truth.', tag: '가상 스토리 장소 — 칼립소의 진실 고백', tag_en: 'STORY SETTING — Calypso reveals the truth', travelTip: '', travelTip_en: '' },
  { id: 'odysseus_arrow_vengeance_hill', order: 101, modernName: '폴리페무스에게 재차 활을 쏘는 언덕', description: '탈출에 성공하고도 죽은 부하들이 떠올라 분노한 오디세우스가 실명한 폴리페무스에게 재차 활을 쏘아, 도리어 포세이돈의 저주를 확정짓는 장소.', description_en: 'Where Odysseus, enraged by memories of his dead men, shoots the blinded Polyphemus again after escaping — sealing Poseidon\'s curse upon them.', tag: '가상 스토리 장소 — 오디세우스의 복수 화살', tag_en: 'STORY SETTING — Odysseus\'s vengeful second arrow at Polyphemus', travelTip: '', travelTip_en: '' },
  { id: 'odysseus_zeus_defiance_vow', order: 102, modernName: '오디세우스가 신들에게 맞서겠다 선언하는 장소', description: '테이레시아스로부터 자신만이 살아 돌아갈 운명이라는 예언을 들은 오디세우스가, 그렇다면 신들과 맞서 운명을 바꾸겠다고 선언하는 저승의 한 자락.', description_en: 'Where, told by Tiresias that only he is fated to survive, Odysseus vows to defy the gods and change that fate.', tag: '가상 스토리 장소 — 오디세우스의 신에 대한 도전 선언', tag_en: 'STORY SETTING — Odysseus\'s vow to defy the gods', travelTip: '', travelTip_en: '' },
];
if (typeof module !== 'undefined' && module.exports) module.exports = ODYSSEY_LOCATIONS;
